package com.alwayslogoutbutton;

import java.util.Arrays;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.WidgetNode;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * RuneLite's World Hopper opens the in-game world switcher to make each hop, and the game then shows the
 * switcher in the logout tab instead of the Logout window.
 *
 * The switcher has to stay open: the server tracks it, and RuneLite's hopping needs it. So this plugin draws the
 * real Logout window on top of it (where Large Logout and other plugins style it as usual), hides the switcher's
 * own contents, and lays the switcher's working Logout button, made fully transparent, exactly under the Logout window's
 * button. A click there is the player's own click on the game's real Logout button.
 *
 * A Logout window opened client-side is drawn but not wired up by the server, so its own buttons do nothing;
 * their menu entries are removed so they never win the left click. Its World Switcher button is the exception: it
 * becomes a client-only entry that uncovers the switcher already open underneath, so nothing is sent to the server.
 * Clicking World Switcher on the server's real Logout window opens a switcher that is left uncovered.
 */
@Slf4j
@PluginDescriptor(
	name = "Always Logout Button",
	description = "Shows the Logout window in the logout tab instead of the in-game world switcher",
	tags = {"world", "hop", "hopper", "switcher", "logout", "wilderness", "misclick"}
)
public class AlwaysLogoutButtonPlugin extends Plugin
{
	/** Switcher parts hidden while the Logout window is shown. BOTTOM, which holds its Logout button, stays. */
	static final int[] HIDDEN = {
		InterfaceID.Worldswitcher.UNIVERSE_GRAPHIC0,
		InterfaceID.Worldswitcher.TOP,
		InterfaceID.Worldswitcher.MIDDLE,
		InterfaceID.Worldswitcher.TOOLTIP,
		InterfaceID.Worldswitcher.NOFAVOURITES,
		InterfaceID.Worldswitcher.FAVOURITE_1,
		InterfaceID.Worldswitcher.FAVOURITE_2,
	};

	private static final int INVISIBLE = 255;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	private final SwitcherIntent intent = new SwitcherIntent();

	/** Switcher widget layouts as they were before this plugin moved them, restored when it is uncovered. */
	private Layout bottomLayout;
	private Layout buttonLayout;

	@Override
	protected void startUp()
	{
		clientThread.invokeLater(this::showLogoutWindow);
	}

	@Override
	protected void shutDown()
	{
		clientThread.invoke(this::uncover);
		intent.reset();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			intent.reset();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getParam1() == InterfaceID.Logout.WORLD_SWITCHER && overlay() == null)
		{
			intent.clickedWorldSwitcher(client.getTickCount());
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.WORLDSWITCHER && intent.coverOnLoad(client.getTickCount()))
		{
			// Not inside the load callback: the switcher is still being opened.
			clientThread.invokeLater(this::showLogoutWindow);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.WORLDSWITCHER)
		{
			intent.reset();
			// The server is replacing the switcher, usually with the real Logout window. Drop our copy without
			// unloading the Logout widgets, which the real one may now be using.
			clientThread.invokeLater(() ->
			{
				WidgetNode overlay = overlay();
				if (overlay != null)
				{
					close(overlay, false);
				}
			});
		}
	}

	/** Re-applied before every frame: the game's scripts and Large Logout re-lay out the switcher as they redraw it. */
	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (overlay() == null)
		{
			return;
		}
		setSwitcherHidden(true);
		placeLogoutButton();
	}

	/** The Logout window's own buttons are not wired up by the server; keep them from taking the click. */
	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		if (overlay() == null)
		{
			return;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		for (MenuEntry e : entries)
		{
			if (e.getParam1() == InterfaceID.Logout.WORLD_SWITCHER && e.getType() != MenuAction.RUNELITE)
			{
				// Client-only: uncovers the switcher already open underneath. Nothing is sent to the server.
				e.setType(MenuAction.RUNELITE).onClick(c -> clientThread.invokeLater(() ->
				{
					intent.reveal();
					uncover();
				}));
			}
		}
		MenuEntry[] kept = Arrays.stream(entries)
			.filter(e -> e.getType() == MenuAction.RUNELITE || !isLogoutWindowComponent(e.getParam1()))
			.toArray(MenuEntry[]::new);
		if (kept.length != entries.length)
		{
			client.getMenu().setMenuEntries(kept);
		}
	}

	static boolean isLogoutWindowComponent(int componentId)
	{
		return componentId >>> 16 == InterfaceID.LOGOUT;
	}

	private void showLogoutWindow()
	{
		if (intent.wanted() || client.getWidget(InterfaceID.Worldswitcher.UNIVERSE) == null || overlay() != null
			|| logoutWindowOpen())
		{
			return;
		}
		try
		{
			bottomLayout = Layout.of(client.getWidget(InterfaceID.Worldswitcher.BOTTOM));
			buttonLayout = Layout.of(client.getWidget(InterfaceID.Worldswitcher.LOGOUT));
			client.openInterface(InterfaceID.Worldswitcher.UNIVERSE, InterfaceID.LOGOUT, WidgetModalMode.NON_MODAL);
		}
		catch (IllegalStateException | IllegalArgumentException e)
		{
			log.warn("Could not show the Logout window over the world switcher", e);
		}
	}

	/** Our Logout window, mounted inside the switcher, or null. */
	private WidgetNode overlay()
	{
		WidgetNode node = client.getComponentTable().get(InterfaceID.Worldswitcher.UNIVERSE);
		return node != null && node.getId() == InterfaceID.LOGOUT ? node : null;
	}

	/** True when a Logout window is open anywhere, e.g. the server's real one. */
	private boolean logoutWindowOpen()
	{
		for (WidgetNode node : client.getComponentTable())
		{
			if (node.getId() == InterfaceID.LOGOUT)
			{
				return true;
			}
		}
		return false;
	}

	/** Remove our Logout window and put the switcher back as the game laid it out. */
	private void uncover()
	{
		WidgetNode overlay = overlay();
		if (overlay != null)
		{
			close(overlay, true);
		}
		setSwitcherHidden(false);
		if (bottomLayout != null)
		{
			bottomLayout.applyTo(client.getWidget(InterfaceID.Worldswitcher.BOTTOM));
		}
		if (buttonLayout != null)
		{
			buttonLayout.applyTo(client.getWidget(InterfaceID.Worldswitcher.LOGOUT));
		}
		bottomLayout = null;
		buttonLayout = null;
	}

	private void close(WidgetNode node, boolean unload)
	{
		try
		{
			client.closeInterface(node, unload);
		}
		catch (IllegalArgumentException e)
		{
			log.debug("Logout window was already closed", e);
		}
	}

	private void setSwitcherHidden(boolean hidden)
	{
		for (int id : HIDDEN)
		{
			Widget w = client.getWidget(id);
			if (w != null && w.isSelfHidden() != hidden)
			{
				w.setHidden(hidden);
			}
		}
		Widget logout = client.getWidget(InterfaceID.Worldswitcher.LOGOUT);
		if (logout != null)
		{
			logout.setOpacity(hidden ? INVISIBLE : 0);
		}
	}

	/** Lay the switcher's (invisible) Logout button exactly over the Logout window's button. */
	private void placeLogoutButton()
	{
		Widget target = client.getWidget(InterfaceID.Logout.LOGOUT);
		Widget universe = client.getWidget(InterfaceID.Worldswitcher.UNIVERSE);
		Widget bottom = client.getWidget(InterfaceID.Worldswitcher.BOTTOM);
		Widget button = client.getWidget(InterfaceID.Worldswitcher.LOGOUT);
		if (target == null || target.isHidden() || universe == null || bottom == null || button == null)
		{
			return;
		}

		// BOTTOM covers the whole tab so the button can sit anywhere in it without being clipped.
		if (bottom.getXPositionMode() != WidgetPositionMode.ABSOLUTE_LEFT || bottom.getOriginalX() != 0
			|| bottom.getYPositionMode() != WidgetPositionMode.ABSOLUTE_TOP || bottom.getOriginalY() != 0
			|| bottom.getWidthMode() != WidgetSizeMode.MINUS || bottom.getOriginalWidth() != 0
			|| bottom.getHeightMode() != WidgetSizeMode.MINUS || bottom.getOriginalHeight() != 0)
		{
			bottom.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT).setOriginalX(0)
				.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP).setOriginalY(0)
				.setWidthMode(WidgetSizeMode.MINUS).setOriginalWidth(0)
				.setHeightMode(WidgetSizeMode.MINUS).setOriginalHeight(0)
				.revalidate();
		}

		Point origin = bottom.getCanvasLocation();
		Point at = target.getCanvasLocation();
		int x = at.getX() - origin.getX();
		int y = at.getY() - origin.getY();
		int w = target.getWidth();
		int h = target.getHeight();
		if (button.getXPositionMode() != WidgetPositionMode.ABSOLUTE_LEFT || button.getOriginalX() != x
			|| button.getYPositionMode() != WidgetPositionMode.ABSOLUTE_TOP || button.getOriginalY() != y
			|| button.getWidthMode() != WidgetSizeMode.ABSOLUTE || button.getOriginalWidth() != w
			|| button.getHeightMode() != WidgetSizeMode.ABSOLUTE || button.getOriginalHeight() != h)
		{
			button.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT).setOriginalX(x)
				.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP).setOriginalY(y)
				.setWidthMode(WidgetSizeMode.ABSOLUTE).setOriginalWidth(w)
				.setHeightMode(WidgetSizeMode.ABSOLUTE).setOriginalHeight(h)
				.revalidate();
		}
	}

	/** A widget's position and size settings. */
	private static final class Layout
	{
		private final int xMode, x, yMode, y, wMode, w, hMode, h;

		private Layout(Widget v)
		{
			xMode = v.getXPositionMode();
			x = v.getOriginalX();
			yMode = v.getYPositionMode();
			y = v.getOriginalY();
			wMode = v.getWidthMode();
			w = v.getOriginalWidth();
			hMode = v.getHeightMode();
			h = v.getOriginalHeight();
		}

		static Layout of(Widget v)
		{
			return v == null ? null : new Layout(v);
		}

		void applyTo(Widget v)
		{
			if (v != null)
			{
				v.setXPositionMode(xMode).setOriginalX(x).setYPositionMode(yMode).setOriginalY(y)
					.setWidthMode(wMode).setOriginalWidth(w).setHeightMode(hMode).setOriginalHeight(h)
					.revalidate();
			}
		}
	}
}

package com.alwayslogoutbutton;

/**
 * Decides whether the world switcher should be covered by the Logout window.
 *
 * RuneLite's World Hopper opens the switcher with no click from the player; that one gets covered. When the player
 * asks for it, by clicking World Switcher on the Logout window, it stays visible until it closes or the player
 * leaves the world.
 */
final class SwitcherIntent
{
	/** Ticks a World Switcher click waits for the switcher to load before it is forgotten. */
	static final int CLICK_WINDOW = 5;

	private int clickTick = -1;
	private boolean wanted;

	/** The player clicked World Switcher on the server's real Logout window. */
	void clickedWorldSwitcher(int tick)
	{
		clickTick = tick;
	}

	/** The player clicked World Switcher on the covering Logout window: uncover the switcher now. */
	void reveal()
	{
		wanted = true;
		clickTick = -1;
	}

	/** The switcher just loaded. True when it should be covered. */
	boolean coverOnLoad(int tick)
	{
		if (clickTick >= 0 && tick - clickTick <= CLICK_WINDOW)
		{
			wanted = true;
		}
		clickTick = -1;
		return !wanted;
	}

	/** True while the player wants the switcher visible. */
	boolean wanted()
	{
		return wanted;
	}

	/** The switcher closed, or the player hopped or logged out. */
	void reset()
	{
		wanted = false;
		clickTick = -1;
	}
}

package com.alwayslogoutbutton;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class AlwaysLogoutButtonPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(AlwaysLogoutButtonPlugin.class);
		RuneLite.main(args);
	}
}

package com.alwayslogoutbutton;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;

public class HiddenWidgetsTest
{
	@Test
	public void switcherLogoutButtonAndItsContainerStayVisible()
	{
		for (int id : AlwaysLogoutButtonPlugin.HIDDEN)
		{
			assertNotEquals(InterfaceID.Worldswitcher.LOGOUT, id);
			assertNotEquals(InterfaceID.Worldswitcher.BOTTOM, id);
			assertNotEquals(InterfaceID.Worldswitcher.UNIVERSE, id);
		}
	}

	@Test
	public void onlyLogoutWindowEntriesAreDropped()
	{
		assertTrue(AlwaysLogoutButtonPlugin.isLogoutWindowComponent(InterfaceID.Logout.LOGOUT));
		assertTrue(AlwaysLogoutButtonPlugin.isLogoutWindowComponent(InterfaceID.Logout.WORLD_SWITCHER));
		assertFalse("the working button must keep its entry",
			AlwaysLogoutButtonPlugin.isLogoutWindowComponent(InterfaceID.Worldswitcher.LOGOUT));
	}
}

package com.alwayslogoutbutton;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class SwitcherIntentTest
{
	@Test
	public void hopperOpenedSwitcherIsCovered()
	{
		assertTrue(new SwitcherIntent().coverOnLoad(100));
	}

	@Test
	public void switcherOpenedByThePlayerStaysVisible()
	{
		SwitcherIntent intent = new SwitcherIntent();
		intent.clickedWorldSwitcher(100);
		assertFalse(intent.coverOnLoad(101));
		assertTrue(intent.wanted());
	}

	@Test
	public void staleClickDoesNotUncoverALaterHop()
	{
		SwitcherIntent intent = new SwitcherIntent();
		intent.clickedWorldSwitcher(100);
		assertTrue(intent.coverOnLoad(100 + SwitcherIntent.CLICK_WINDOW + 1));
	}

	@Test
	public void revealLastsUntilTheSwitcherClosesOrThePlayerHops()
	{
		SwitcherIntent intent = new SwitcherIntent();
		intent.reveal();
		assertTrue(intent.wanted());
		intent.reset();
		assertFalse(intent.wanted());
		assertTrue(intent.coverOnLoad(200));
	}
}
